\set ON_ERROR_STOP on
begin;
insert into auth.users(id) select ('00000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid from generate_series(1,8)n;
create function pg_temp.assert_true(ok boolean,description text) returns void language plpgsql as $$begin if ok is distinct from true then raise exception 'FAILED: %',description;end if;end$$;
create function pg_temp.expect_failure(command text,description text) returns void language plpgsql as $$declare failed boolean:=false;begin begin execute command;exception when others then failed:=true;end;if not failed then raise exception 'FAILED (unexpected success): %',description;end if;end$$;
set local role authenticated;
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000001',true);
insert into contests(id,host_id,title,fields,participation_mode,team_min_size,team_max_size,allow_individual_entries,registration_closes_at,event_start_at,ends_at) values
 ('60000000-0000-4000-8000-000000000001',auth.uid(),'Team contest','[{"id":"20000000-0000-4000-8000-000000000001","type":"file","label":"Report","description":"","required":false,"extensions":".pdf","max_size_mb":1}]','team',2,2,true,clock_timestamp()+interval '1 hour',clock_timestamp()+interval '2 hours',clock_timestamp()+interval '3 hours');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000002',true);
select * from register_contest_entry('60000000-0000-4000-8000-000000000001','Captain','{}','team_create','First');
set constraints all immediate;
select set_config('test.team',(select id::text from contest_teams),true);
select set_config('test.code',(select join_code::text from contest_teams),true);
select pg_temp.expect_failure($q$insert into contest_submissions(contest_id,user_id,team_id,participant_name,answers)values('60000000-0000-4000-8000-000000000001',auth.uid(),current_setting('test.team')::uuid,'First','{}')$q$,'underfilled team cannot submit');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000003',true);
select * from register_contest_entry('60000000-0000-4000-8000-000000000001','Member','{}','team_join',null,current_setting('test.code')::uuid);
insert into storage.objects(bucket_id,name,metadata)values('contest-submissions','60000000-0000-4000-8000-000000000001/00000000-0000-4000-8000-000000000003/20000000-0000-4000-8000-000000000001/report.pdf','{"size":123}');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000002',true);
insert into contest_submissions(contest_id,user_id,team_id,participant_name,answers)values('60000000-0000-4000-8000-000000000001',auth.uid(),current_setting('test.team')::uuid,'First','{"20000000-0000-4000-8000-000000000001":{"path":"60000000-0000-4000-8000-000000000001/00000000-0000-4000-8000-000000000003/20000000-0000-4000-8000-000000000001/report.pdf","name":"report.pdf","size":123}}');
select pg_temp.assert_true((select count(*)=1 from storage.objects),'captain reads teammate file');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000003',true);
update contest_submissions set participant_name='Shared update' where team_id=current_setting('test.team')::uuid;
select pg_temp.assert_true((select participant_name='Shared update' and user_id='00000000-0000-4000-8000-000000000002' from contest_submissions),'teammate updates without changing original submitter');
delete from storage.objects where bucket_id='contest-submissions';
select pg_temp.assert_true((select count(*)=1 from storage.objects),'uploader cannot remove shared referenced file');
select pg_temp.expect_failure($q$insert into contest_submissions(contest_id,user_id,team_id,participant_name,answers) values('60000000-0000-4000-8000-000000000001',auth.uid(),current_setting('test.team')::uuid,'Duplicate','{}')$q$,'only one shared submission per team');
select pg_temp.expect_failure($q$update contest_submissions set user_id=auth.uid()$q$,'shared editor cannot replace original submitter');
select pg_temp.expect_failure($q$update contest_submissions set team_id=null$q$,'shared editor cannot remove team identity');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000004',true);
select pg_temp.assert_true((select count(*)=0 from contest_teams),'outsider cannot read team invite code');
select pg_temp.assert_true((select count(*)=0 from contest_submissions),'outsider cannot read shared submission');
select pg_temp.assert_true((select count(*)=0 from storage.objects),'outsider cannot read team file');
select pg_temp.expect_failure($q$select * from register_contest_entry('60000000-0000-4000-8000-000000000001','Overflow','{}','team_join',null,current_setting('test.code')::uuid)$q$,'maximum size enforced atomically');
set constraints all immediate;
select pg_temp.expect_failure($q$insert into event_registrations(contest_id,user_id,attendee_name,participation_kind)values('60000000-0000-4000-8000-000000000001',auth.uid(),'Raw bypass','team')$q$,'raw REST team registration cannot omit membership');
select * from register_contest_entry('60000000-0000-4000-8000-000000000001','Second captain','{}','team_create','Second');
select set_config('test.secondteam',(select id::text from contest_teams),true);
select set_config('test.secondcode',(select join_code::text from contest_teams),true);
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000005',true);
select * from register_contest_entry('60000000-0000-4000-8000-000000000001','Second member','{}','team_join',null,current_setting('test.secondcode')::uuid);
select pg_temp.expect_failure($q$insert into contest_submissions(contest_id,user_id,team_id,participant_name,answers)values('60000000-0000-4000-8000-000000000001',auth.uid(),current_setting('test.team')::uuid,'Spoof','{}')$q$,'cannot submit as another team');
select pg_temp.expect_failure($q$insert into contest_submissions(contest_id,user_id,team_id,participant_name,answers)values('60000000-0000-4000-8000-000000000001',auth.uid(),current_setting('test.secondteam')::uuid,'Stolen file','{"20000000-0000-4000-8000-000000000001":{"path":"60000000-0000-4000-8000-000000000001/00000000-0000-4000-8000-000000000003/20000000-0000-4000-8000-000000000001/report.pdf","name":"report.pdf","size":123}}')$q$,'another team file reference denied');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000006',true);
select * from register_contest_entry('60000000-0000-4000-8000-000000000001','Solo','{}','individual');
select pg_temp.assert_true((select count(*)=0 from contest_team_members),'solo queued for allocator, no fabricated membership');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000001',true);
select pg_temp.expect_failure($q$update contests set team_max_size=1,team_min_size=1 where id='60000000-0000-4000-8000-000000000001'$q$,'host cannot shrink below existing teams');
select pg_temp.expect_failure($q$update contests set allow_individual_entries=false where id='60000000-0000-4000-8000-000000000001'$q$,'host cannot disable existing solo entries');
-- Cancellation removes only membership; submission data survives team deletion.
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000003',true);
update event_registrations set status='cancelled' where user_id=auth.uid();
select pg_temp.assert_true((select count(*)=0 from contest_team_members),'cancelled member loses team access');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000002',true);
update event_registrations set status='cancelled' where user_id=auth.uid();
select pg_temp.assert_true((select team_id is null and participant_name='Shared update' from contest_submissions),'last cancellation retains original submission');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000001',true);
update contests set registration_closes_at=clock_timestamp()-interval '1 minute' where id='60000000-0000-4000-8000-000000000001';
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000007',true);
select pg_temp.expect_failure($q$select * from register_contest_entry('60000000-0000-4000-8000-000000000001','Late','{}','individual')$q$,'server deadline blocks registration');
select 'TEAM_SHARED_SUBMISSION_CONTRACTS_PASSED';
rollback;
